```
#include <DHT.h>

// Define the DHT22 pin connections
#define DHTPIN 2
#define DHTTYPE DHT22

// Define the calibration parameters
const float temperatureCalibrationCoeff = 1.0; // Calibration coefficient for temperature
const float humidityCalibrationCoeff = 1.0; // Calibration coefficient for humidity

DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  int temperature = dht.readTemperature();
  int humidity = dht.readHumidity();

  // Apply calibration coefficients
  temperature = temperature * temperatureCalibrationCoeff;
  humidity = humidity * humidityCalibrationCoeff;

  // Print the calibrated values
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.print("°C");
  Serial.print("\t");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println("%");
  delay(2000); // wait 2 seconds before next reading
}
```
